package dev.freeneo.app;

import java.util.HexFormat;

public final class FlightCommandTest {
    public static void main(String[] args) {
        var hex = HexFormat.of();
        var takeoff = new FlightCommand(FlightCommand.Action.TAKEOFF, 0x1234);
        var land = new FlightCommand(FlightCommand.Action.LAND, 0x1234);
        var confirm = new FlightCommand(FlightCommand.Action.CONFIRM_LANDING, 0x1234);
        // Fixtures generated by the pinned Python reference.
        check(hex.formatHex(takeoff.request()).equals("550e04660203341240032a0128b1"));
        check(hex.formatHex(land.request()).equals("550e04660203341240032a02b383"));
        check(hex.formatHex(confirm.request()).equals("550e04660203341240032a1e5e59"));
        check(hex.formatHex(land.forward(0x12345678, 0x87654321, 0x76543210)).equals(
            "553104533be91032005101550e04660203341240032a02b38378563412021032547621436587018200000000000000dc54"));
        check(land.acknowledge(hex.parseHex("550e04660302341280032a001285")).orElseThrow().accepted());
        check(land.acknowledge(hex.parseHex("550e04660302341280032a0200a6")).orElseThrow().status() == 2);
        check(land.acknowledge(PairingExchange.frame(3, 2, 0x1235, 0x80, 3, 0x2a, new byte[] {0})).isEmpty());
        check(land.acknowledge(hex.parseHex("550e04660302341280032a001284")).isEmpty());
        check(land.acknowledge(land.request()).isEmpty());
        System.out.println("Flight command codec checks passed");
    }

    private static void check(boolean result) {
        if (!result) throw new AssertionError("Unexpected flight command codec result");
    }
}
